CREATE TABLE public.primary_administrator (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), user_id uuid NOT NULL UNIQUE);
GRANT SELECT ON public.primary_administrator TO authenticated;
GRANT ALL ON public.primary_administrator TO service_role;
ALTER TABLE public.primary_administrator ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_self ON public.primary_administrator FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_primary_administrator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND coalesce(auth.jwt()->>'aal','')='aal2' AND EXISTS(SELECT 1 FROM public.primary_administrator p WHERE p.user_id=auth.uid()) AND public.has_role(auth.uid(),'admin'); $$;
REVOKE ALL ON FUNCTION public.is_primary_administrator() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_primary_administrator() TO authenticated, service_role;
CREATE FUNCTION public.require_primary_administrator(recent boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE verified_at bigint; BEGIN IF NOT public.is_primary_administrator() THEN RAISE EXCEPTION 'Primary administrator and multi-factor authentication required' USING ERRCODE='42501'; END IF; IF recent THEN SELECT max((entry->>'timestamp')::bigint) INTO verified_at FROM jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) entry WHERE entry->>'method' IN ('totp','mfa'); IF verified_at IS NULL OR to_timestamp(verified_at)<now()-interval '5 minutes' THEN RAISE EXCEPTION 'Verify an authenticator code again before this action' USING ERRCODE='42501'; END IF; END IF; END; $$;
REVOKE ALL ON FUNCTION public.require_primary_administrator(boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.require_primary_administrator(boolean) TO authenticated;
CREATE TABLE public.admin_customers (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_ref text NOT NULL UNIQUE DEFAULT ('AU-'||upper(replace(gen_random_uuid()::text,'-',''))), account_ref text NOT NULL UNIQUE DEFAULT ('DEMO-'||upper(replace(gen_random_uuid()::text,'-',''))),
 first_name text NOT NULL, middle_name text NOT NULL DEFAULT '', last_name text NOT NULL, date_of_birth date, nationality text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', email text NOT NULL, phone text NOT NULL DEFAULT '', alternative_phone text NOT NULL DEFAULT '', account_type text NOT NULL DEFAULT 'Personal', currency text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Active','Suspended','Restricted','Closed')), opening_date date NOT NULL DEFAULT current_date, verification_status text NOT NULL DEFAULT 'Unverified' CHECK(verification_status IN ('Unverified','In review','Verified')), notes text NOT NULL DEFAULT '', archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
 CHECK(length(first_name) BETWEEN 1 AND 80), CHECK(length(last_name) BETWEEN 1 AND 80), CHECK(length(email)<=255), CHECK(account_type IN ('Personal','Business','Savings','Wealth')), CHECK(currency IN ('USD','EUR','GBP','CAD','CHF'))
);
GRANT SELECT ON public.admin_customers TO authenticated;
GRANT ALL ON public.admin_customers TO service_role;
ALTER TABLE public.admin_customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_customers ON public.admin_customers FOR SELECT TO authenticated USING(public.is_primary_administrator());
CREATE UNIQUE INDEX admin_customer_email_unique ON public.admin_customers(lower(email)) WHERE archived_at IS NULL;
CREATE TABLE public.admin_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE DEFAULT ('APP-'||upper(replace(gen_random_uuid()::text,'-',''))), first_name text NOT NULL, last_name text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', account_type text NOT NULL DEFAULT 'Personal', currency text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Information requested','Approved','Rejected')), verification_status text NOT NULL DEFAULT 'Unverified' CHECK(verification_status IN ('Unverified','In review','Verified')), customer_id uuid REFERENCES public.admin_customers(id), review_reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(account_type IN ('Personal','Business','Savings','Wealth')), CHECK(currency IN ('USD','EUR','GBP','CAD','CHF')));
GRANT SELECT ON public.admin_applications TO authenticated;
GRANT ALL ON public.admin_applications TO service_role;
ALTER TABLE public.admin_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_applications ON public.admin_applications FOR SELECT TO authenticated USING(public.is_primary_administrator());
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, entity_type text NOT NULL, entity_id uuid, action text NOT NULL, reason text NOT NULL DEFAULT '', old_values jsonb, new_values jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated;
GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_audit ON public.admin_audit FOR SELECT TO authenticated USING(public.is_primary_administrator());
CREATE TABLE public.admin_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, entity_id uuid, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.admin_notifications TO authenticated;
GRANT ALL ON public.admin_notifications TO service_role;
ALTER TABLE public.admin_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_notifications ON public.admin_notifications FOR SELECT TO authenticated USING(public.is_primary_administrator());
CREATE TABLE public.admin_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES public.admin_customers(id), transaction_type text NOT NULL, amount numeric(18,2) NOT NULL, currency text NOT NULL, status text NOT NULL CHECK(status IN ('Completed','Pending','Failed','Reversed')), occurred_at timestamptz NOT NULL, provider_reference text NOT NULL);
GRANT SELECT ON public.admin_transactions TO authenticated;
GRANT ALL ON public.admin_transactions TO service_role;
ALTER TABLE public.admin_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_transactions ON public.admin_transactions FOR SELECT TO authenticated USING(public.is_primary_administrator());
COMMENT ON TABLE public.admin_transactions IS 'Read-only authorized provider records. No transaction fabrication or money movement workflows enabled.';
CREATE TABLE public.admin_preferences (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT 'Administrator', security_notifications boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_preferences TO authenticated;
GRANT ALL ON public.admin_preferences TO service_role;
ALTER TABLE public.admin_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY primary_preferences ON public.admin_preferences FOR SELECT TO authenticated USING(public.is_primary_administrator() AND user_id=auth.uid());
CREATE INDEX admin_audit_date ON public.admin_audit(created_at DESC);
CREATE INDEX admin_customers_date ON public.admin_customers(created_at DESC);
CREATE FUNCTION public.audit_admin_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE act text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'An authenticated administrator is required'; END IF; act:=CASE WHEN TG_OP='INSERT' THEN 'Created' ELSE 'Updated' END; IF TG_TABLE_NAME='admin_customers' AND TG_OP='UPDATE' THEN IF NEW.archived_at IS NOT NULL AND OLD.archived_at IS NULL THEN act:='Archived'; ELSIF NEW.status IS DISTINCT FROM OLD.status THEN act:=NEW.status; END IF; END IF; INSERT INTO public.admin_audit(actor_id,entity_type,entity_id,action,reason,old_values,new_values) VALUES(auth.uid(),TG_TABLE_NAME,NEW.id,act,coalesce(current_setting('app.admin_reason',true),''),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); INSERT INTO public.admin_notifications(title,entity_id) VALUES(CASE WHEN TG_TABLE_NAME='admin_customers' THEN 'Customer record ' ELSE 'Application ' END||lower(act),NEW.id); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.audit_admin_record() FROM PUBLIC;
CREATE TRIGGER customer_audit AFTER INSERT OR UPDATE ON public.admin_customers FOR EACH ROW EXECUTE FUNCTION public.audit_admin_record();
CREATE TRIGGER application_audit AFTER INSERT OR UPDATE ON public.admin_applications FOR EACH ROW EXECUTE FUNCTION public.audit_admin_record();
CREATE FUNCTION public.admin_save_customer(payload jsonb, record_id uuid DEFAULT NULL, expected_version integer DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN PERFORM public.require_primary_administrator(false); IF payload ? 'password' OR payload ? 'pin' THEN RAISE EXCEPTION 'Credentials are not permitted'; END IF; IF coalesce(payload->>'first_name','')='' OR coalesce(payload->>'last_name','')='' OR coalesce(payload->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Complete valid customer details are required'; END IF; IF record_id IS NULL THEN INSERT INTO public.admin_customers(first_name,middle_name,last_name,date_of_birth,nationality,country,address,email,phone,alternative_phone,account_type,currency,opening_date,notes) VALUES(payload->>'first_name',coalesce(payload->>'middle_name',''),payload->>'last_name',nullif(payload->>'date_of_birth','')::date,coalesce(payload->>'nationality',''),coalesce(payload->>'country',''),coalesce(payload->>'address',''),lower(payload->>'email'),coalesce(payload->>'phone',''),coalesce(payload->>'alternative_phone',''),coalesce(payload->>'account_type','Personal'),coalesce(payload->>'currency','USD'),coalesce(nullif(payload->>'opening_date','')::date,current_date),coalesce(payload->>'notes','')) RETURNING id INTO result; ELSE PERFORM set_config('app.admin_reason','Customer details updated',true); UPDATE public.admin_customers SET first_name=payload->>'first_name',middle_name=coalesce(payload->>'middle_name',''),last_name=payload->>'last_name',date_of_birth=nullif(payload->>'date_of_birth','')::date,nationality=coalesce(payload->>'nationality',''),country=coalesce(payload->>'country',''),address=coalesce(payload->>'address',''),email=lower(payload->>'email'),phone=coalesce(payload->>'phone',''),alternative_phone=coalesce(payload->>'alternative_phone',''),account_type=payload->>'account_type',currency=payload->>'currency',notes=coalesce(payload->>'notes',''),updated_at=now(),version=version+1 WHERE id=record_id AND archived_at IS NULL AND version=expected_version RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Record changed or is unavailable; reload before saving'; END IF; END IF; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.admin_save_customer(jsonb,uuid,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_save_customer(jsonb,uuid,integer) TO authenticated;
CREATE FUNCTION public.admin_change_customer(record_id uuid, target_status text, reason text, checks_complete boolean DEFAULT false, archive boolean DEFAULT false, expected_version integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.require_primary_administrator(true); IF length(trim(reason))<5 OR length(reason)>1000 THEN RAISE EXCEPTION 'Document a reason of 5 to 1000 characters'; END IF; IF target_status NOT IN ('Pending','Active','Suspended','Restricted','Closed') THEN RAISE EXCEPTION 'Invalid status'; END IF; IF target_status='Active' AND NOT checks_complete THEN RAISE EXCEPTION 'Confirm required demonstration checks'; END IF; IF archive AND target_status<>'Closed' THEN RAISE EXCEPTION 'Close the record before archiving'; END IF; PERFORM set_config('app.admin_reason',reason,true); UPDATE public.admin_customers SET status=target_status,archived_at=CASE WHEN archive THEN now() ELSE NULL END,updated_at=now(),version=version+1 WHERE id=record_id AND archived_at IS NULL AND version=expected_version; IF NOT FOUND THEN RAISE EXCEPTION 'Record changed or is unavailable; reload before saving'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.admin_change_customer(uuid,text,text,boolean,boolean,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_change_customer(uuid,text,text,boolean,boolean,integer) TO authenticated;
CREATE FUNCTION public.admin_create_application(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN PERFORM public.require_primary_administrator(false); IF coalesce(payload->>'first_name','')='' OR coalesce(payload->>'last_name','')='' OR coalesce(payload->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Valid applicant details required'; END IF; INSERT INTO public.admin_applications(first_name,last_name,email,phone,account_type,currency) VALUES(payload->>'first_name',payload->>'last_name',lower(payload->>'email'),coalesce(payload->>'phone',''),payload->>'account_type',payload->>'currency') RETURNING id INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.admin_create_application(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_create_application(jsonb) TO authenticated;
CREATE FUNCTION public.admin_review_application(record_id uuid, decision text, reason text, checks_complete boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE application public.admin_applications; customer uuid; BEGIN PERFORM public.require_primary_administrator(true); IF length(trim(reason))<5 OR length(reason)>1000 THEN RAISE EXCEPTION 'A documented review reason is required'; END IF; IF decision NOT IN ('Information requested','Approved','Rejected') THEN RAISE EXCEPTION 'Invalid decision'; END IF; SELECT * INTO application FROM public.admin_applications WHERE id=record_id FOR UPDATE; IF NOT FOUND OR application.status IN ('Approved','Rejected') THEN RAISE EXCEPTION 'Application unavailable or already reviewed'; END IF; PERFORM set_config('app.admin_reason',reason,true); IF decision='Approved' THEN IF NOT checks_complete THEN RAISE EXCEPTION 'Confirm demonstration checks before approval'; END IF; INSERT INTO public.admin_customers(first_name,last_name,email,phone,account_type,currency,status) VALUES(application.first_name,application.last_name,application.email,application.phone,application.account_type,application.currency,'Pending') RETURNING id INTO customer; END IF; UPDATE public.admin_applications SET status=decision,customer_id=customer,review_reason=reason,updated_at=now() WHERE id=record_id; RETURN customer; END; $$;
REVOKE ALL ON FUNCTION public.admin_review_application(uuid,text,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_review_application(uuid,text,text,boolean) TO authenticated;
CREATE FUNCTION public.admin_mark_notifications(record_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.require_primary_administrator(false); UPDATE public.admin_notifications SET read_at=now() WHERE read_at IS NULL AND (record_id IS NULL OR id=record_id); END; $$;
REVOKE ALL ON FUNCTION public.admin_mark_notifications(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_mark_notifications(uuid) TO authenticated;
CREATE FUNCTION public.admin_save_preferences(display_name text, security_notifications boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.require_primary_administrator(false); IF length(trim(display_name)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid name'; END IF; INSERT INTO public.admin_preferences(user_id,display_name,security_notifications) VALUES(auth.uid(),display_name,security_notifications) ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name,security_notifications=excluded.security_notifications,updated_at=now(); INSERT INTO public.admin_audit(actor_id,entity_type,action,reason) VALUES(auth.uid(),'preferences','Updated','Administrator preferences updated'); END; $$;
REVOKE ALL ON FUNCTION public.admin_save_preferences(text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_save_preferences(text,boolean) TO authenticated;
CREATE FUNCTION public.admin_record_access(event text DEFAULT 'Workspace opened') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.require_primary_administrator(false); IF event NOT IN ('Workspace opened','Report exported','Password changed','Other sessions signed out') THEN RAISE EXCEPTION 'Invalid event'; END IF; INSERT INTO public.admin_audit(actor_id,entity_type,action) VALUES(auth.uid(),'security',event); END; $$;
REVOKE ALL ON FUNCTION public.admin_record_access(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_record_access(text) TO authenticated;